class Coin(int number) { public int Number = number; }
class Input {
 public List<Dictionary<string,int>> Values = [{"key":7}];
 public List<int> Empty = [];
 public List<int> Numbers = [3,4];
 public Dictionary<string,int> Map = {"key":7};
 public Set<int> NumbersSet = [3,4];
 public Set<Reference<Coin>> Picks = [];
 public Coin C = new Coin(9);
}
class Generic<T>(Reference<T> value) { public Reference<T> Value = value; }
class Concrete(Reference<List<int>> value) { public Reference<List<int>> Value = value; }
class Written { public Reference<List<int>> Value; public Written(Reference<List<int>> value) { Value = value; } }
class SetReference(Reference<Set<int>> value) { public Reference<Set<int>> Value = value; }
class SelectionReference(Reference<Set<Reference<Coin>>> value) { public Reference<Set<Reference<Coin>>> Value = value; }
class Probe {
 @storage(allowed: .Session) public static Input Saved = new();
 public static int Mixed() { Generic<List<Dictionary<string,int>>> x = new(Reference(Saved.Values)); return x.Value[0]["key"]; }
 public static int Empty() { Generic<List<int>> x = new(Reference(Saved.Empty)); return x.Value.Count; }
 public static int Multiple() { Generic<List<int>> x = new(Reference(Saved.Numbers)); return x.Value.Count; }
 public static int Dictionary() { Generic<Dictionary<string,int>> x = new(Reference(Saved.Map)); return x.Value["key"]; }
 public static int Set() { SetReference x = new(Reference(Saved.NumbersSet)); return x.Value.Count; }
 public static int Selection() { Saved.Picks.Add(Saved.C); SelectionReference x = new(Reference(Saved.Picks)); return x.Value.First().Number; }
 public static int Concrete() { Concrete x = new(Reference(Saved.Numbers)); return x.Value[1]; }
 public static int Body() { Written x = new(Reference(Saved.Numbers)); return x.Value[1]; }
 public static int LiveAlias() { Generic<List<int>> x = new(Reference(Saved.Numbers)); Saved.Numbers.Add(5); return x.Value.Count; }
 public static int ReferenceSlot() { Generic<int> x = new(Reference(Saved.C.Number)); return x.Value; }
 public static int ReferenceClass() { Generic<Coin> x = new(Reference(Saved.C)); return x.Value.Number; }
}
